    let l = (max + min) / 2.0_f32;
    let delta = max - min;
    let mut h = if max == r {
        60.0_f32 * ((g - b) / delta)
    } else if max == g {
        60.0_f32 * (((b - r) / delta) + 2.0_f32)
    } else {
        60.0_f32 * (((r - g) / delta) + 4.0_f32)
    };
    if h < 0.0 { h += 360.0; }
    let s = delta / (1.0_f32 - (2.0_f32 * l - 1.0_f32).abs());
    println!("hsl f32: {:.9} {:.9} {:.9}", h, s, l);

