    let mind = if if gd < bd { gd } else { bd } < rd { if gd < bd { gd } else { bd } } else { rd };
    let ld = (maxd + mind) / 2.0_f64;
    if maxd == mind { println!("gray"); return; }
    let deltad = maxd - mind;
    let mut hd = if maxd == rd {
        60.0_f64 * ((gd - bd) / deltad)
    } else if maxd == gd {
        60.0_f64 * (((bd - rd) / deltad) + 2.0_f64)
    } else {
        60.0_f64 * (((rd - gd) / deltad) + 4.0_f64)
    };
    if hd < 0.0 { hd += 360.0; }
    let sd = deltad / (1.0_f64 - (2.0_f64 * ld - 1.0_f64).abs());
    println!("hsl f64: {:.9} {:.9} {:.9}", hd, sd, ld);
}
